async () => {
  const zones = (await cloudflare.request({ method: 'GET', path: '/zones', query: { per_page: 50 } })).result;
  const hits = [];
  for (const zone of zones) {
    const records = await cloudflare.request({
      method: 'GET',
      path: `/zones/${zone.id}/dns_records`,
      query: { content: '203.0.113.40', proxied: true },
    });
    for (const r of records.result) hits.push({ zone: zone.name, name: r.name, type: r.type, proxied: r.proxied });
  }
  return hits;
}
